float frombits(uint32_t b){float f;memcpy(&f,&b,4);return f;}
int main(){const int n=4096,nb=64;std::vector<float>p(n*2),g(n*2),ms(nb),vs(nb);std::vector<int8_t>m(n),v(n);for(int i=0;i<n*2;i++){p[i]=float(i%31-15)/16;g[i]=float(i%17-8)/64;}for(int i=0;i<nb;i++){ms[i]=float(i%7+1)/16;vs[i]=float(i%5+1)/32;}for(int i=0;i<n;i++){m[i]=(i%8+8)|(((3*i)%8+8)<<4);v[i]=(i%16)|(((7*i)%16)<<4);}float *dp,*dg,*dms,*dvs;int8_t*dm,*dv;cudaMalloc(&dp,n*8);cudaMalloc(&dg,n*8);cudaMalloc(&dms,nb*4);cudaMalloc(&dvs,nb*4);cudaMalloc(&dm,n);cudaMalloc(&dv,n);auto reset=[&](){cudaMemcpy(dp,p.data(),n*8,cudaMemcpyHostToDevice);cudaMemcpy(dg,g.data(),n*8,cudaMemcpyHostToDevice);cudaMemcpy(dms,ms.data(),nb*4,cudaMemcpyHostToDevice);cudaMemcpy(dvs,vs.data(),nb*4,cudaMemcpyHostToDevice);cudaMemcpy(dm,m.data(),n,cudaMemcpyHostToDevice);cudaMemcpy(dv,v.data(),n,cudaMemcpyHostToDevice);cudaDeviceSynchronize();};uint32_t params[2][3]={{1036831952u,1023510188u,1008981768u},{1044549472u,1027023248u,1001158287u}};auto run=[&](){for(int step=0;step<2;step++){float c1=frombits(params[step][0]),c2=frombits(params[step][1]),ss=frombits(params[step][2]);fused_4bit_kernel<float,64><<<64,64>>>(dp,dg,dms,dvs,dm,dv,.9f,.999f,.001f,.01f,1e-8f,float(step+1),n,c1,c2,ss,1.f-.001f*.01f,1.f-.9f,1.f-.999f);}};auto wp=p,wm=ms,wv=vs;auto wmb=m,wvb=v;for(int step=0;step<2;step++)reference<float,64>(64,wp.data(),g.data(),wm.data(),wv.data(),wmb.data(),wvb.data(),.9f,.999f,.001f,.01f,1e-8f,float(step+1),n,frombits(params[step][0]),frombits(params[step][1]),frombits(params[step][2]),1.f-.001f*.01f,1.f-.9f,1.f-.999f);std::vector<double>want;for(auto x:wp)want.push_back(x);for(auto x:wmb)want.push_back(uint8_t(x));for(auto x:wvb)want.push_back(uint8_t(x));for(auto x:wm)want.push_back(x);for(auto x:wv)want.push_back(x);reset();run();if(cudaDeviceSynchronize()!=cudaSuccess)return 2;
for(int trial=1;trial<=5;trial++){reset();auto t=std::chrono::steady_clock::now();run();if(cudaDeviceSynchronize()!=cudaSuccess)return 2;double seconds=std::chrono::duration<double>(std::chrono::steady_clock::now()-t).count()/2;std::vector<float>op(n*2),om(nb),ov(nb);std::vector<uint8_t>obm(n),obv(n);cudaMemcpy(op.data(),dp,n*8,cudaMemcpyDeviceToHost);cudaMemcpy(om.data(),dms,nb*4,cudaMemcpyDeviceToHost);cudaMemcpy(ov.data(),dvs,nb*4,cudaMemcpyDeviceToHost);cudaMemcpy(obm.data(),dm,n,cudaMemcpyDeviceToHost);cudaMemcpy(obv.data(),dv,n,cudaMemcpyDeviceToHost);std::vector<double>out;for(auto x:op)out.push_back(x);for(auto x:obm)out.push_back(x);for(auto x:obv)out.push_back(x);for(auto x:om)out.push_back(x);for(auto x:ov)out.push_back(x);double err=0;bool ok=true;for(size_t i=0;i<out.size();i++){err=std::max(err,fabs(out[i]-want[i]));ok=ok&&std::isfinite(out[i])&&fabs(out[i]-want[i])<=1e-3;}char path[64];snprintf(path,sizeof(path),"trial_%d.bin",trial);FILE*f=fopen(path,"wb");fwrite(out.data(),8,out.size(),f);fclose(f);printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.15g,\"correct\":%s,\"checked_values\":%zu,\"max_abs_error\":%.15g,\"timing_region\":\"mean_two_sequential_optimizer_steps_excluding_reset\",\"jit_excluded\":true,\"internal_repeats\":2,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float64\",\"count\":%zu,\"byte_order\":\"little\"}}\n",trial,seconds,ok?"true":"false",out.size(),err,path,out.size());if(!ok)return 1;}cudaFree(dp);cudaFree(dg);cudaFree(dms);cudaFree(dvs);cudaFree(dm);cudaFree(dv);}
